export const ENDING_QUESTION='君は、この石を私に渡してよかったと思うか？';
export function transferEndingStone(collected=[]){
 const stone=collected.find(id=>id.startsWith('blue-shard-'))??null;
 return {stone,remaining:stone?collected.filter(id=>id!==stone):[...collected]};
}
